import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }

// --- SVG PATHS ---
// A simplified brain hemisphere shape
const HEMISPHERE_PATH = "M -2 40 C -40 10 -100 0 -130 50 C -160 100 -140 210 -80 230 C -30 240 -10 200 -2 190 Z";
const VEIN_PATH_1 = "M -50 60 C -70 80 -60 120 -80 140";
const VEIN_PATH_2 = "M -90 80 C -110 90 -120 130 -110 160";
const VEIN_PATH_3 = "M -40 160 C -60 180 -50 200 -70 210";

// --- SUB-COMPONENTS ---

const HumanBrain: React.FC<{
  color1: string;
  color2: string;
  pulseSpeed: number;
}> = ({ color1, color2, pulseSpeed }) => {
  const frame = useCurrentFrame();
  
  // Organic pulse animation
  const scale = interpolate(
    Math.sin(frame * pulseSpeed * 0.1),
    [-1, 1],
    [0.98, 1.02]
  );
  
  const glowOpacity = interpolate(
    Math.sin(frame * pulseSpeed * 0.1),
    [-1, 1],
    [0.5, 0.8]
  );

  return (
    <div style={{ transform: `scale(${scale})`, position: "relative" }}>
      <svg width="300" height="300" viewBox="-150 0 300 300" style={{ overflow: "visible" }}>
        <defs>
          <linearGradient id="humanGradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={color1} />
            <stop offset="100%" stopColor={color2} />
          </linearGradient>
          <filter id="humanGlow">
            <feGaussianBlur stdDeviation="15" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        <g filter="url(#humanGlow)">
           {/* Left Hemisphere */}
           <path d={HEMISPHERE_PATH} fill="url(#humanGradient)" opacity={0.9} />
           {/* Right Hemisphere (Mirrored) */}
           <path d={HEMISPHERE_PATH} fill="url(#humanGradient)" transform="scale(-1, 1)" opacity={0.9} />
        </g>

        {/* Synapses / Veins */}
        <g stroke="rgba(255,255,255,0.4)" strokeWidth="2" fill="none" strokeLinecap="round">
           <path d={VEIN_PATH_1} />
           <path d={VEIN_PATH_2} />
           <path d={VEIN_PATH_3} />
           <path d={VEIN_PATH_1} transform="scale(-1, 1)" />
           <path d={VEIN_PATH_2} transform="scale(-1, 1)" />
           <path d={VEIN_PATH_3} transform="scale(-1, 1)" />
        </g>
        
        {/* Active Synapse Pulses */}
        <circle r="3" fill="white" filter="drop-shadow(0 0 2px white)">
           <animateMotion dur="3s" repeatCount="indefinite" path={VEIN_PATH_1} />
        </circle>
        <circle r="3" fill="white" filter="drop-shadow(0 0 2px white)">
           <animateMotion dur="4s" begin="1s" repeatCount="indefinite" path={VEIN_PATH_2} transform="scale(-1, 1)" />
        </circle>
      </svg>
    </div>
  );
};

const AIBrain: React.FC<{
  color: string;
}> = ({ color }) => {
  const frame = useCurrentFrame();

  // Generate binary grid
  const binaryGrid = useMemo(() => {
    const rows = 12;
    const cols = 20;
    return Array.from({ length: rows * cols }).map((_, i) => ({
      val: i % 2 === 0 ? "1" : "0",
      x: (i % cols) * 15 - 140,
      y: Math.floor(i / cols) * 20 + 20,
      id: i,
    }));
  }, []);

  return (
    <div style={{ position: "relative" }}>
      <svg width="300" height="300" viewBox="-150 0 300 300" style={{ overflow: "visible" }}>
        <defs>
          <clipPath id="brainClip">
             <path d={HEMISPHERE_PATH} />
             <path d={HEMISPHERE_PATH} transform="scale(-1, 1)" />
          </clipPath>
          <filter id="aiGlow">
            <feGaussianBlur stdDeviation="8" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        {/* Outline / Container */}
        <g filter="url(#aiGlow)">
           <path d={HEMISPHERE_PATH} fill={`${color}22`} stroke={color} strokeWidth="2" />
           <path d={HEMISPHERE_PATH} transform="scale(-1, 1)" fill={`${color}22`} stroke={color} strokeWidth="2" />
        </g>

        {/* Binary Content masked inside brain */}
        <g clipPath="url(#brainClip)">
          {binaryGrid.map((bit) => {
             // Random flicker logic
             const seed = `bit-${bit.id}-${Math.floor(frame / 5)}`;
             const opacity = interpolate(random(seed), [0, 1], [0.1, 0.9]);
             const isActive = random(seed) > 0.8; 
             
             return (
               <text
                 key={bit.id}
                 x={bit.x}
                 y={bit.y}
                 fill={isActive ? "#ffffff" : color}
                 fillOpacity={opacity}
                 fontSize="12"
                 fontFamily="Share Tech Mono"
                 textAnchor="middle"
               >
                 {bit.val}
               </text>
             );
          })}
        </g>
      </svg>
    </div>
  );
};


